INSERT INTO academy_courses (slug, title, description, icon, color, order_index, difficulty, requires_pro, is_published) VALUES
  ('macro-basics', 'Macro Basics: How the Economy Moves Stocks', 'Your stocks don''t move in a vacuum. Learn how the Fed, jobs reports, inflation, and oil prices ripple into the market, and the habit of checking the bigger picture before you assume something''s wrong with your own picks.', 'Landmark', 'sky', 12, 'beginner', FALSE, TRUE)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO academy_lessons (course_id, slug, title, type, order_index, xp_reward, content)
SELECT
  (SELECT id FROM academy_courses WHERE slug = 'macro-basics'),
  v.slug, v.title, v.type, v.order_index, v.xp_reward, v.content
FROM (VALUES
  ('stocks-dont-move-alone', 'Stocks Don''t Move Alone', 'read', 0, 10, '{"sections":[{"text":"Imagine every stock as a boat floating in the same ocean. Some days a single boat rocks because of its own news, and other days the whole ocean rises or falls and lifts every boat at once. That bigger ocean is the overall economy, and it moves many stocks together. Learning to tell these two forces apart is one of the most useful skills a new investor can build.","highlightedTerms":[]},{"text":"The first bucket is company-specific catalysts: things that happen to one business. This includes earnings reports, a new product launch, or a change in leadership. These events explain why one stock might jump or drop while its competitors barely move.","highlightedTerms":[{"term":"Earnings","definition":"When the company next reports its quarterly results. Prices often move sharply around earnings dates."}]},{"text":"The second bucket is macro catalysts: big-picture events that push many stocks at the same time. When the Federal Reserve changes its interest rate, or a monthly jobs report or inflation data comes out, the whole market can swing together. None of these are about any single company, yet they affect nearly all of them.","highlightedTerms":[{"term":"Federal Reserve","definition":"The United States central bank. It sets interest rate policy to try to keep inflation in check and the economy growing at a healthy pace."},{"term":"Interest Rate","definition":"What it costs to borrow money, set in large part by the Fed''s policy rate. When rates rise, loans, mortgages, and business borrowing all get more expensive."},{"term":"Jobs Report","definition":"A US government report, released the first Friday of most months, showing how many jobs were added or lost. Markets react to whether the number beats or misses forecasts, not the number itself."}]},{"text":"Here is the contrast that makes it click. A well-run company with zero bad news can still see its stock fall on a day the Fed signals higher rates, simply because the whole market dropped. Meanwhile, a struggling company''s stock can rally on a strong jobs report that lifts everything at once. So before you assume something is wrong with a stock specifically, check whether the whole market moved together that day. That one habit will save you from a lot of false alarms.","highlightedTerms":[{"term":"Inflation","definition":"The rate at which prices for goods and services increase over time. High inflation erodes what your money can buy and often pushes the Fed to raise interest rates."}]}],"funFact":"Markets can react to a Federal Reserve announcement in under a second. Automated trading systems scan the exact wording and fire off orders almost instantly, sometimes moving prices before a human has finished reading the first sentence."}'::jsonb),
  ('the-big-four-macro-forces', 'The Big Four: Rates, Jobs, Inflation, Oil', 'read', 1, 10, '{"sections":[{"text":"The Federal Reserve is like a thermostat for the economy. When things get too hot and prices climb too fast, it raises interest rates to cool things down; when the economy needs a boost, it cuts rates to encourage spending and growth. Higher rates make borrowing more expensive for both companies and everyday people, and that extra cost tends to weigh on stock prices across the board.","highlightedTerms":[{"term":"Federal Reserve","definition":"The United States central bank. It sets interest rate policy to try to keep inflation in check and the economy growing at a healthy pace."},{"term":"Interest Rate","definition":"What it costs to borrow money, set in large part by the Fed''s policy rate. When rates rise, loans, mortgages, and business borrowing all get more expensive."}]},{"text":"Every month, a Jobs Report shows how many people found work. Here''s the surprising part: markets react to the difference between the number and what investors expected, not the raw number itself. A much stronger or weaker report than forecast is read as a clue about what the Federal Reserve might do next with interest rates, rather than a simple thumbs-up or thumbs-down on the economy.","highlightedTerms":[{"term":"Jobs Report","definition":"A US government report, released the first Friday of most months, showing how many jobs were added or lost. Markets react to whether the number beats or misses forecasts, not the number itself."}]},{"text":"Inflation is the rate at which prices for everyday goods and services rise over time. It is the main reason the Federal Reserve adjusts interest rates in the first place: too much inflation, and the Fed steps in to slow it down. So when you hear about rising prices, think of it as the trigger that sets rate decisions in motion.","highlightedTerms":[{"term":"Inflation","definition":"The rate at which prices for goods and services increase over time. High inflation erodes what your money can buy and often pushes the Fed to raise interest rates."}]},{"text":"Oil prices touch almost everything, from the cost of shipping goods to the price you pay at the pump. When oil gets more expensive, transportation and manufacturing costs rise, which can push up consumer prices and change energy company profits. The full story is more nuanced, but for now just know that oil is one of the big forces investors keep an eye on.","highlightedTerms":[{"term":"Oil Price","definition":"The market price of crude oil. It ripples into transportation and manufacturing costs, consumer prices, and energy company profits, sometimes pulling the market in two different directions at once."}]}],"funFact":"A jobs report that looks great for workers can sometimes make stocks fall, because investors worry a strong economy will push the Federal Reserve to raise interest rates."}'::jsonb),
  ('macro-basics-quiz', 'Quick Check: Macro Basics', 'quiz', 2, 20, '{"questions":[{"question":"The Federal Reserve just raised its interest rate by 0.5%. What tends to happen to stock prices across the market?","options":["They tend to rise because higher rates mean a stronger economy","They tend to fall because borrowing gets more expensive for companies and consumers","Nothing changes, since rates don''t affect stocks","They always crash by exactly the same amount as the rate hike"],"correctIndex":1,"explanation":"When the Fed raises rates, loans get pricier for everyone. Companies pay more to borrow and grow, and consumers spend less, so investors often expect lower profits and stock prices tend to drift down."},{"question":"A jobs report expected 150,000 new jobs, but the actual number came in at 300,000. Why might stocks fall on this news even though it sounds like great news?","options":["Strong jobs always make stocks rally, so this is a mistake","A too-hot number raises the odds the Fed keeps rates higher for longer","Companies fired workers, which is bad for the economy","More jobs means less money for investors"],"correctIndex":1,"explanation":"A jobs number way above forecast can signal an economy running too hot. Investors worry the Fed will keep rates high to cool things down, and higher rates are a headwind for stocks."},{"question":"A supply disruption causes oil prices to spike sharply. What is the most likely effect on the stock market?","options":["Every company''s stock falls by the same amount","Every company''s stock rises because oil is valuable","Energy company profits could rise while airlines and consumer companies get squeezed by higher costs","Only the Fed is affected, not any companies"],"correctIndex":2,"explanation":"A price spike doesn''t push the whole market one way. Oil producers can earn more, but businesses that burn a lot of fuel, like airlines and shippers, face higher costs that eat into their profits."}]}'::jsonb),
  ('macro-terms-match', 'Match the Macro Terms', 'match', 3, 15, '{"pairs":[{"term":"Federal Reserve (the Fed)","definition":"The U.S. central bank that sets money policy."},{"term":"Interest Rate","definition":"The cost of borrowing money, shown as a percent."},{"term":"Jobs Report","definition":"A monthly update on how many people are working."},{"term":"Inflation","definition":"When prices for stuff go up over time."},{"term":"CPI","definition":"A number that tracks the price of everyday goods."},{"term":"Oil Price","definition":"How much one barrel of crude oil costs."}]}'::jsonb),
  ('is-it-them-or-the-market', 'Is It Them, or the Market?', 'scenario', 4, 25, '{"setup":"You open your app and see one of your stocks is down 4 percent today. You check the company''s page: no earnings report, no news headlines, nothing about the business itself has changed. Your gut says something must be wrong. What do you do?","choices":[{"label":"Sell right away. A drop with no news feels like a warning sign.","feedback":"Totally understandable to feel spooked, but selling before you understand why skips the most useful step. A price drop is a question, not an answer. Selling first means you might dump a good company just because the whole market had a rough day.","isCorrect":false},{"label":"Check if the whole market dropped too, and look for big-picture news like a Fed announcement or a hot inflation report.","feedback":"Exactly right. When a solid company falls with no company-specific news, the cause is often macro, meaning it affects the whole market at once. If the S&P 500 is also down and there was a Fed rate decision or a scary inflation report, your stock is likely just moving with the crowd. This one habit will save you from a lot of panic selling.","isCorrect":true},{"label":"Ignore it completely. Daily moves never mean anything.","feedback":"You are right that most single-day wiggles are just noise, and that''s a healthier instinct than panic selling. But brushing off every move is its own trap. Taking two minutes to ask ''is this the company or the whole market?'' is still worth it, even when the answer turns out to be nothing to worry about.","isCorrect":false}]}'::jsonb)
) AS v(slug, title, type, order_index, xp_reward, content)
ON CONFLICT (course_id, slug) DO NOTHING;
